import { createServer as httpsServer } from "node:https";
import { request } from "node:http";
import { createServer as tlsServer } from "node:tls";
import { connect } from "node:net";
import { readFileSync } from "node:fs";
import { spawn } from "node:child_process";

// Local TLS termination exercises the same Secure-cookie/rediss requirements as production.
// The certificate is generated by run-readiness.mjs and trusted only by its child processes.
const tlsOptions = { cert: readFileSync(process.env.READINESS_TLS_CERT), key: readFileSync(process.env.READINESS_TLS_KEY) };
const child = spawn(process.execPath, ["node_modules/next/dist/bin/next", "start", "--port", "3302", "--hostname", "127.0.0.1"], { stdio: "inherit", windowsHide: true, env: process.env });
const sockets = new Set();
const redis = tlsServer(tlsOptions, (socket) => {
  sockets.add(socket);
  const upstream = connect(56379, "127.0.0.1");
  socket.pipe(upstream).pipe(socket);
  socket.on("error", () => upstream.destroy());
  upstream.on("error", () => socket.destroy());
  socket.on("close", () => { upstream.destroy(); sockets.delete(socket); });
});
const web = httpsServer(tlsOptions, (incoming, outgoing) => {
  const upstream = request({ hostname: "127.0.0.1", port: 3302, path: incoming.url, method: incoming.method, headers: { ...incoming.headers, "x-forwarded-proto": "https" } }, (response) => {
    outgoing.writeHead(response.statusCode ?? 502, response.headers);
    response.pipe(outgoing);
  });
  upstream.on("error", () => { if (!outgoing.headersSent) outgoing.writeHead(503); outgoing.end(); });
  incoming.on("error", () => upstream.destroy());
  incoming.pipe(upstream);
});
redis.listen(56380, "127.0.0.1");
web.listen(3301, "127.0.0.1");
let closing = false;
function close(code = 0) {
  if (closing) return;
  closing = true;
  child.kill();
  for (const socket of sockets) socket.destroy();
  web.closeAllConnections();
  web.close();
  redis.close();
  process.exitCode = code;
}
for (const server of [redis, web]) server.on("error", (error) => { console.error(error.message); close(1); });
child.on("error", (error) => { console.error(error.message); close(1); });
child.on("exit", (code) => close(code ?? 1));
for (const signal of ["SIGTERM", "SIGINT"]) process.on(signal, () => close());
